/**
 * Hand-curated app-level row types — NOT a generated artifact.
 *
 * These interfaces describe the subset of columns the application
 * code reads and are narrower / more opinionated than the raw
 * `Database['public']['Tables'][…]['Row']` types generated by the
 * Supabase CLI. They are imported by DAL helpers, server components,
 * and the admin UI wherever typed row objects are needed without the
 * full Insert/Update generics.
 *
 * Source of truth: this file is hand-edited.  Whenever a column is
 * added, renamed, or dropped in a migration, update the matching
 * interface here in the same PR.
 *
 * See also:
 *   - `types/supabase.ts`                — GENERATED `Database` type
 *                                          consumed by
 *                                          `createClient<Database>()`.
 *   - `scripts/check-schema-drift.sh`    — regenerates `types/supabase.ts`
 *                                          from the live DB; this file
 *                                          is intentionally NOT regenerated.
 */

// ── Affiliate Clicks ───────────────────────────────────────────────────

export interface AffiliateClickRow {
  id: string;
  click_id: string | null;
  click_ref: string | null;
  product_id: string | null;
  site_id: string;
  product_name: string;
  affiliate_url: string;
  content_slug: string;
  referrer: string;
  created_at: string;
}

export interface AffiliateLinkHealthRow {
  id: string;
  site_id: string;
  product_id: string;
  product_affiliate_link_id: string | null;
  url: string;
  network: string;
  last_probed_at: string | null;
  last_http_status: number | null;
  final_url: string | null;
  baseline_registrable_domain: string | null;
  latency_ms: number | null;
  consecutive_failures: number;
  failure_streak_started_at: string | null;
  classification: "healthy" | "broken" | "suspicious";
  created_at: string;
  updated_at: string;
}

export interface SiteRow {
  id: string;
  slug: string;
  name: string;
  domain: string;
  language: string;
  direction: "ltr" | "rtl";
  is_active: boolean;

  // Monetization
  monetization_type: "affiliate" | "ads" | "both";
  est_revenue_per_click: number;
  ad_config: Record<string, unknown>;

  // Theming
  theme: Record<string, unknown>;
  logo_url: string | null;
  favicon_url: string | null;

  // Navigation
  nav_items: { label: string; href: string; icon?: string }[];
  footer_nav: { label: string; href: string; icon?: string }[];

  // Features
  features: Record<string, boolean>;

  // SEO
  meta_title: string | null;
  meta_description: string | null;
  og_image_url: string | null;
  url_redirects?: Array<{
    source_path: string;
    destination_path: string;
    permanent?: boolean;
  }> | null;

  // Social links
  social_links: Record<string, string>;

  // Template / layout
  homepage_template: HomepageTemplate;
  product_card_style: ProductCardStyle;

  created_at: string;
  updated_at: string;
}

type HomepageTemplate =
  | "standard"
  | "cinematic"
  | "minimal"
  | "editorial"
  | "top10"
  | "compare"
  | "showcase";
type ProductCardStyle = "standard" | "compact" | "detailed";

export type TaxonomyType = "general" | "budget" | "occasion" | "recipient" | "brand" | "style";

export interface CategoryRow {
  id: string;
  site_id: string;
  name: string;
  slug: string;
  description: string;
  taxonomy_type: TaxonomyType;
  created_at: string;
}

export interface ProductRow {
  id: string;
  site_id: string;
  name: string;
  slug: string;
  description: string;
  affiliate_url: string;
  image_url: string;
  image_alt: string;
  price: string;
  price_amount: number | null;
  price_currency: string;
  merchant: string;
  score: number | null;
  featured: boolean;
  status: "draft" | "active" | "archived";
  category_id: string | null;
  category_ids?: string[] | null;
  cta_text: string;
  deal_text: string;
  deal_expires_at: string | null;
  pros: string;
  cons: string;
  /** ISO18-001: Optimistic locking version — incremented on every update. */
  version: number;
  created_at: string;
  updated_at: string;
}

