export interface ContentRow {
  id: string;
  site_id: string;
  title: string;
  slug: string;
  body: string;
  excerpt: string;
  featured_image: string;
  type: "article" | "review" | "comparison" | "guide" | "blog";
  status: "draft" | "review" | "published" | "scheduled" | "archived";
  category_id: string | null;
  tags: string[];
  author: string | null;
  author_id?: string | null;
  publish_at: string | null;
  meta_title: string | null;
  meta_description: string | null;
  og_image: string | null;
  body_previous: string | null;
  review_state: "draft" | "awaiting_edit" | "edited" | "published";
  /** SEC-13: true when this row was created or edited by an AI pipeline. DB default: false. */
  ai_generated?: boolean;
  /** SEC-13: timestamp of most recent human editorial review. */
  human_reviewed_at?: string | null;
  created_at: string;
  updated_at: string;
}

